#include <Adafruit_GFX.h>    // Графическая библиотека
#include <Adafruit_ST7735.h> // Драйвер для ST7735
#include <SPI.h>             // Библиотека для SPI шины

// Определяем пины к которым подключен дисплей
#define TFT_CS    10  // Chip Select (CS)
#define TFT_RST   9   // Reset (RES)
#define TFT_DC    8   // Data/Command (DC)

// Создаем объект дисплея
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

void setup() {
  Serial.begin(9600);
  Serial.println("Запуск 1.8" дисплея...");

  // Инициализация с помощью специальной команды для 1.8" 128x160
  // Используем INITR_BLACKTAB — это вариант для черного (или красного) шлейфа 1.8"
  // Если экран показывает инвертированные цвета, можно заменить на INITR_REDTAB
  tft.initR(INITR_BLACKTAB);

  // Переворачиваем экран, если текст или картинка отображаются вверх ногами
  // tft.setRotation(1); // Раскомментируйте, если изображение перевернуто

  // Заливаем экран черным цветом
  tft.fillScreen(ST77XX_BLACK);

  // ---- Рисуем тестовую картинку ----

  // 1. Рисуем красный прямоугольник
  tft.fillRect(10, 10, 50, 50, ST77XX_RED);

  // 2. Рисуем синий прямоугольник
  tft.fillRect(70, 10, 50, 50, ST77XX_BLUE);

  // 3. Рисуем зеленый прямоугольник
  tft.fillRect(40, 70, 50, 50, ST77XX_GREEN);

  // 4. Выводим текст
  tft.setTextSize(2);          // Размер шрифта (1 - маленький, 2 - средний)
  tft.setTextColor(ST77XX_YELLOW); // Цвет текста
  tft.setCursor(20, 130);      // Позиция X, Y (нижняя часть экрана)
  tft.print("Hello, World!");

  Serial.println("Готово!");
}

void loop() {
  // Здесь можно написать анимацию, если нужно
  // Например, мигание подсветкой или вывод данных с датчиков
}
